function ridgeTrails(grid) {
  const h = grid.length, w = grid[0].length;
  const memo = grid.map((row) => row.map(() => 0));
  const walk = (r, c) => {
    if (memo[r][c]) return memo[r][c];
    let longest = 1;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < h && nc >= 0 && nc < w && grid[nr][nc] > grid[r][c]) longest = Math.max(longest, 1 + walk(nr, nc));
    }
    memo[r][c] = longest;
    return longest;
  };
  let best = 0;
  for (let r = 0; r < h; r++) for (let c = 0; c < w; c++) best = Math.max(best, walk(r, c));
  return best;
}
